import java.io.*;
/** Rebind a finished room to a re-authenticated owner without discarding their pending picks. */
final class ResultResume {
 static final long RETAIN_MILLIS=30*60*1000L;
 static boolean retain(GunnyServer.Room room,long now){if(room.phase!=2||room.battle==null||!room.battle.over||now-room.lastActive>RETAIN_MILLIS)return false;for(var member:room.members)if(member!=null&&!room.returned.contains(member.id)&&room.rewardEligible(member))return true;return false;}

 static boolean receiving(GunnyServer server,GunnyServer.Session member){if(member==null)return false;var r=server.rooms.get(member.room);if(r==null||r.phase!=2)return false;var b=r.battle;if(b==null||!b.over||r.kind==3&&b.winner!=0)return false;int seat=r.slot(member),damage=0;if(seat<0)return false;for(int i=0;i<r.count;i++)if(r.avatars[i].owner==member)damage+=b.damage[i];return Progression.reward(b.winner,seat%2,damage)&&r.cardPicks.getOrDefault(member.id,0)<DungeonRewards.picks(r.kind,r.dungeonStage);}
 static boolean reconnect(GunnyServer server,GunnyServer.Session old,GunnyServer.Session fresh){var room=server.rooms.get(old.room);if(room==null||room.phase!=2||room.battle==null||!room.battle.over||room.host.delta!=fresh.delta)return false;synchronized(room){int seat=room.slot(old);if(seat<0)return false;room.members[seat]=fresh;room.avatars[seat].owner=fresh;if(room.host==old)room.host=fresh;var home=room.returnRooms.remove(old);if(home!=null){room.returnRooms.put(fresh,home);synchronized(home){int at=home.slot(old);if(at>=0)home.members[at]=fresh;if(home.host==old)home.host=fresh;home.refreshWaiting();}}fresh.room=room.id;fresh.resultAck=old.resultAck;fresh.cardsReady=old.cardsReady;fresh.resolution=old.resolution;fresh.armed=false;return true;}}
 static void write(GunnyServer server,GunnyServer.Session s,DataOutputStream out)throws IOException{var room=server.rooms.get(s.room);boolean valid=room!=null&&room.phase==2&&room.battle!=null&&room.battle.over;out.writeBoolean(valid);if(valid)synchronized(room){server.lobby(out,room,s);out.writeByte(room.battle.winner);out.writeBoolean(room.rewardEligible(s));}}
}
